public interface IComponent { void Show(int depth = 0); }

public class Leaf : IComponent
{
    private string _name;
    public Leaf(string n) { _name = n; }
    public void Show(int depth = 0) => Console.WriteLine(new string(' ', depth * 2) + _name);
}

public class Composite : IComponent
{
    private string _name;
    private List<IComponent> _children = new();
    public Composite(string n) { _name = n; }
    public void Add(IComponent c) => _children.Add(c);
    public void Show(int depth = 0)
    {
        Console.WriteLine(new string(' ', depth * 2) + _name);
        foreach (var c in _children) c.Show(depth + 1);
    }
}

var root = new Composite("根");
root.Add(new Leaf("文件A"));
root.Show();

