public class CharStyle { public string Font { get; } public CharStyle(string f) { Font = f; } }

public class StyleFactory
{
    private Dictionary<string, CharStyle> _pool = new();
    public CharStyle Get(string font) =>
        _pool.TryGetValue(font, out var s) ? s : _pool[font] = new CharStyle(font);  // 共享
