public interface IImage { void Display(); }
public class RealImage : IImage
{
    public RealImage(string file) { Console.WriteLine("加载 " + file); }  // 昂贵
    public void Display() => Console.WriteLine("显示");
}

public class ImageProxy : IImage   // 虚拟代理：延迟加载
{
    private RealImage _real;
    private string _file;
    public ImageProxy(string file) { _file = file; }
    public void Display()
    {
        _real ??= new RealImage(_file);   // 第一次才真正创建
        _real.Display();
    }
}

IImage img = new ImageProxy("a.jpg");
img.Display();   // 此时才加载

public abstract class Handler
{
    protected Handler Next;
    public Handler SetNext(Handler h) { Next = h; return h; }
    public abstract void Handle(int level);
}

public class Low : Handler { public override void Handle(int l) { if (l < 10) Console.WriteLine("Low处理"); else Next?.Handle(l); } }
public class High : Handler { public override void Handle(int l) { if (l >= 10) Console.WriteLine("High处理"); else Next?.Handle(l); } }

var chain = new Low(); chain.SetNext(new High());
chain.Handle(20);

public interface ICommand { void Execute(); void Undo(); }
public class Light { public void On() => Console.WriteLine("开灯"); public void Off() => Console.WriteLine("关灯"); }

public class TurnOn : ICommand
{
    private Light _l;
    public TurnOn(Light l) { _l = l; }
    public void Execute() => _l.On();
    public void Undo() => _l.Off();
}

var history = new Stack<ICommand>();
ICommand cmd = new TurnOn(new Light());
cmd.Execute(); history.Push(cmd);
history.Pop().Undo();

