public interface IState { void Handle(Context c); }
public class Context { public IState State { get; set; } public void Request() => State.Handle(this); }

public class Idle : IState { public void Handle(Context c) { Console.WriteLine("空闲→运行"); c.State = new Running(); } }
public class Running : IState { public void Handle(Context c) { Console.WriteLine("运行→停止"); c.State = new Stopped(); } }
public class Stopped : IState { public void Handle(Context c) { Console.WriteLine("已停止"); } }

var ctx = new Context { State = new Idle() };
ctx.Request(); ctx.Request(); ctx.Request();

