public abstract class DataProcessor
{
    public sealed void Run()   // 算法骨架，固定
    {
        Load(); Transform(); Save();
    }
    protected abstract void Load();
    protected virtual void Transform() { }   // 钩子，可选
    protected abstract void Save();
}

