public interface IVisitor { void Visit(ElementA a); void Visit(ElementB b); }
public interface IElement { void Accept(IVisitor v); }
public class ElementA : IElement { public void Accept(IVisitor v) => v.Visit(this); }
public class ElementB : IElement { public void Accept(IVisitor v) => v.Visit(this); }

public class ExportVisitor : IVisitor   // 新操作：导出，不改动元素类
{
    public void Visit(ElementA a) => Console.WriteLine("导出A");
    public void Visit(ElementB b) => Console.WriteLine("导出B");
}

IElement[] items = { new ElementA(), new ElementB() };
var v = new ExportVisitor();
foreach (var e in items) e.Accept(v);
